// ## API Contract — GET /v1/orders/{id}   (producer: Orders Service)
// Compatibility rule: additive-only within a major version.
//   ADD optional field  -> safe, no version bump
//   RENAME/REMOVE field -> BREAKING -> ship as /v2, keep /v1 for 90d

interface OrderV1 {
  id: string            // required, stable
  status: 'pending' | 'paid' | 'shipped'  // required, closed enum
  total_cents: number   // required — NEVER rename in v1 (3 consumers read it)
  currency: string      // required, ISO-4217
  note?: string         // OPTIONAL — safe to add, consumers must tolerate absence
}

// Error envelope is part of the contract — every non-2xx uses this shape:
interface ApiError {
  code: 'ORDER_NOT_FOUND' | 'UNAUTHORIZED' | 'RATE_LIMITED'  // closed set
  message: string       // human-readable, safe to log, never leaks internals
  retryable: boolean    // tells the consumer whether to back off + retry
}
// 404 -> { code: 'ORDER_NOT_FOUND', message: 'no order for id', retryable: false }

